- Input: 21x15 grid of 1s with three 6s scattered in column 5 (at rows 2, 6, 10)
- Output: Column 5 is completely filled with 6s (all 21 rows)

The rule is: **Find columns that contain any "marker" color (different from background), and fill the entire column with that marker color.**

```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find the most common value (background)
    values = [cell for row in grid for cell in row]
    from collections import Counter
    counter = Counter(values)
    background = max(counter, key=counter.get)

    # Find marker colors (values different from background)
    markers = []
    for cell in set(counter.keys()):
        if cell != background:
            markers.append(cell)

    if not markers:
        return grid

    marker_color = markers[0]  # Assume single marker color

    # Find which columns contain marker colors
    marker_cols = set()
    for col in range(cols):
        for row in range(rows):
            if grid[row][col] == marker_color:
                marker_cols.add(col)
                break

    # Build output grid
    result = [[background] * cols for _ in range(rows)]

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == marker_color:
                result[row][col] = marker_color
            elif col in marker_cols:
                result[row][col] = marker_color

    return result
